function validate([synonyms, text]) {
  const isWord = (w) => typeof w === 'string' && /^[A-Za-z]+$/.test(w);
  if (!Array.isArray(synonyms) || synonyms.length > 10) return 'Give at most 10 synonym pairs.';
  const keys = new Set();
  for (const pair of synonyms) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each synonym pair has exactly two words.';
    const [s, t] = pair;
    if (!isWord(s) || !isWord(t) || s.length > 10 || t.length > 10) return 'Synonym words have 1 to 10 English letters.';
    if (s === t) return 'The two words of a pair must differ.';
    if (keys.has(`${s} ${t}`) || keys.has(`${t} ${s}`)) return 'A pair of words is listed twice.';
    keys.add(`${s} ${t}`);
  }
  if (typeof text !== 'string') return 'text must be a string.';
  const words = text.split(' ');
  if (words.length > 10) return 'text has at most 10 words.';
  if (!words.every(isWord)) return 'text is English-letter words separated by single spaces.';
  // Keep the answer small enough for the local judge.
  const parent = new Map();
  const find = (w) => (parent.get(w) === w ? w : find(parent.get(w)));
  for (const [s, t] of synonyms) {
    if (!parent.has(s)) parent.set(s, s);
    if (!parent.has(t)) parent.set(t, t);
    parent.set(find(s), find(t));
  }
  const groupSize = new Map();
  for (const w of parent.keys()) groupSize.set(find(w), (groupSize.get(find(w)) || 0) + 1);
  let count = 1;
  for (const w of words) count *= parent.has(w) ? groupSize.get(find(w)) : 1;
  if (count > 20000) return 'This input makes more than 20,000 sentences, too many for the local judge.';
  return null;
}

