function generateSentences(synonyms, text) {
  const parent = new Map();
  const find = (word) => {
    while (parent.get(word) !== word) {
      parent.set(word, parent.get(parent.get(word)));
      word = parent.get(word);
    }
    return word;
  };
  for (const [first, second] of synonyms) {
    if (!parent.has(first)) parent.set(first, first);
    if (!parent.has(second)) parent.set(second, second);
    parent.set(find(first), find(second));
  }

  const groups = new Map();
  for (const word of parent.keys()) {
    const root = find(word);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(word);
  }
  for (const group of groups.values()) {
    group.sort();
  }

  const words = text.split(' ');
  const result = [];
  const current = [];
  const build = (index) => {
    if (index === words.length) {
      result.push(current.join(' '));
      return;
    }
    const word = words[index];
    const options = parent.has(word) ? groups.get(find(word)) : [word];
    for (const option of options) {
      current.push(option);
      build(index + 1);
      current.pop();
    }
  };
  build(0);
  return result;
}

