function generateSentences(synonyms, text) {
  // Swap one word for a direct synonym at a time until no new sentence appears, then sort.
  const found = new Set([text]);
  const pending = [text];
  while (pending.length > 0) {
    const words = pending.pop().split(' ');
    for (let i = 0; i < words.length; i++) {
      for (const [a, b] of synonyms) {
        for (const [from, to] of [[a, b], [b, a]]) {
          if (words[i] !== from) continue;
          const next = [...words.slice(0, i), to, ...words.slice(i + 1)].join(' ');
          if (!found.has(next)) {
            found.add(next);
            pending.push(next);
          }
        }
      }
    }
  }
  return [...found].sort();
}

