function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const small = size === 'small';
  const letters = small ? 'abc' : 'abcdefghijklmnopqrstuvwxyz';
  const makeWord = () => {
    const length = 1 + pick(small ? 3 : 10);
    let word = '';
    for (let i = 0; i < length; i++) word += letters[pick(letters.length)];
    return rand() < 0.1 ? word[0].toUpperCase() + word.slice(1) : word;
  };
  for (;;) {
    const pool = Array.from({ length: small ? 2 + pick(5) : 12 + pick(9) }, makeWord);
    const pairCount = small ? pick(5) : 8 + pick(3);
    const synonyms = [];
    const keys = new Set();
    for (let tries = 0; synonyms.length < pairCount && tries < 100; tries++) {
      const s = pool[pick(pool.length)];
      const t = pool[pick(pool.length)];
      if (s === t || keys.has(`${s} ${t}`) || keys.has(`${t} ${s}`)) continue;
      keys.add(`${s} ${t}`);
      synonyms.push([s, t]);
    }
    const wordCount = small ? 1 + pick(5) : 10;
    const words = Array.from({ length: wordCount }, () => (rand() < (small ? 0.6 : 0.4) ? pool[pick(pool.length)] : makeWord()));
    // Count the sentences (product of group sizes) so the answer stays a reasonable size.
    const links = new Map();
    for (const [s, t] of synonyms) {
      if (!links.has(s)) links.set(s, []);
      if (!links.has(t)) links.set(t, []);
      links.get(s).push(t);
      links.get(t).push(s);
    }
    const groupSize = (word) => {
      if (!links.has(word)) return 1;
      const seen = new Set([word]);
      const stack = [word];
      while (stack.length) for (const next of links.get(stack.pop())) if (!seen.has(next)) { seen.add(next); stack.push(next); }
      return seen.size;
    };
    const count = words.reduce((product, word) => product * groupSize(word), 1);
    if (small ? count <= 200 : count >= 100 && count <= 2000) return [synonyms, words.join(' ')];
  }
}
